import json,pathlib,collections
out=pathlib.Path('/workspace/overload-head/stage3/census/overload-result-10b6c33')
a=json.loads((out/'unit-analysis.json').read_text()); d=json.loads((out/'delta.json').read_text())
p=json.loads((out/'provenance.json').read_text())
def esc(s):return str(s).replace('|','\\|').replace('\n','<br>')
def loc(s):return s.replace('/workspace/overload-adapted/','')
lines=['# Paired overload-result census: task z5d0jye','','Report only. No compiler or adaptation changes.','',f"Parent compiler: `{p['parent']}`. Head compiler: `{p['head']}`. The optimizer branch was checked before setup and still pointed at the requested head.",'',f"Both runs use exactly one adapted tree, produced by efe88776 stage3/apply.sh from TypeScript 6.0.3 `{p['upstream']}`. Both compilers were built from their own SHA with their recorded submodules. The same parent meter latent overlay and entry driver instrument each compiler. `LATENT_FULL=0`, `LATENT_ASSERT_NO_OUTPUT=1`; the tsc entry resolves {len(a['header']['sources'])} source files and has {len(a['header']['diagnostics'])} checker diagnostics. Headers match exactly; both streams have completed relation trailers.",'','## Counts','','| Measure | Parent | Head |','| --- | ---: | ---: |',f"| Units | {a['unit_count']} | {a['unit_count']} |",f"| Attempted units (including recovered panics) | {a['attempted_before']} | {a['attempted_after']} |",f"| Attempted units with no lowering first stop | {a['lowered_before']} | {a['lowered_after']} |",f"| Overload-result first stops | {a['overload_before']} | {a['overload_after']} |",'', '| Paired delta | Raw | Distinct |','| --- | ---: | ---: |']
for label,k in [('Cleared findings with no remaining finding at the identity','lowered'),('Cleared findings with another reason remaining','moved'),('New findings','new_findings'),('New sites','new_sites'),('Changed unit first stops','unit_first_stop_delta'),('Regressions','regressions')]:
 lines.append(f"| {label} | {len(d['raw_findings'][k])} | {len(d['distinct_reads'][k])} |")
for side in ['before','after']:
 for k in sorted(set(d['raw_findings']['totals'][side])|set(d['distinct_reads']['totals'][side])):
  lines.append(f"| {side} {k} | {d['raw_findings']['totals'][side].get(k,0)} | {d['distinct_reads']['totals'][side].get(k,0)} |")
rows=a['targets']; others=a['other_overload']
lines+=['',f"Requested subset: {sum(r['overload_stop_cleared'] for r in rows)}/{len(rows)} overload-result stops clear; {sum(r['lowered'] for r in rows)} units then lower without another lowering finding. Other overload-result subset: {sum(r['unchanged'] for r in others)}/{len(others)} first stops unchanged.",'','A finding disappearing at a source identity is not proof that its enclosing unit lowers. Newly exposed reasons in an already-blocked unit are listed as changed first stops. Regressions are previously finding-free attempted units that now stop, previously finding-free refusal-scan sites that now find, or new panics. Raw and distinct access-chain pairing use stage3/census/pair without modifying the tool. The complete delta, reason transitions, source hashes and panics are in [delta.json](delta.json); [pair-report.md](pair-report.md) is the tool-generated report.','', '## The requested 43 units','',(out/'43-units.md').read_text().strip(),'','## The other 67 overload-result units','',(out/'67-units.md').read_text().strip(),'','## All changed lowering first stops','','| Unit | Unit location | Parent first stop | Head first stop |','| --- | --- | --- | --- |']
for r in a['first_stop_changes']:
 def stop(f):return 'Lowered' if f is None else f"{f['kind']}: {f['reason']} at {loc(f['where'])}"
 lines.append('| '+' | '.join(esc(s) for s in [r['unit'].get('name',r['unit']['kind']),loc(r['unit']['where']),stop(r['base']),stop(r['head'])])+' |')
lines+=['','## Every regression','']
for view in ['raw_findings','distinct_reads']:
 regs=d[view]['regressions'];lines.append(f"{view}: {len(regs)}.")
 for r in regs: lines+=['','```json',json.dumps(r,indent=2),'```']
lines+=['','## Time and peak memory','','Both measurements start after setup and both builds finish. Head overlaps the already-running parent to stay within the environment lifecycle; these timings include that overlap. Each uses a separate output stream and timing wrapper. The parent census exited 0; its outer shell later hit a script-edit syntax error. The completed stream was validated and reused without a compiler rerun. See harness-events.json and overload-parent-measure-original-shell.log. See measurement-scheduling.json. Peak RSS is the child process high-water mark from Linux getrusage, in KiB (MiB below). Each Python wrapper waits for its child, writes its actual exit code and exits with that code. Times include checking, census work and stream writes. Per-unit wall/CPU streams are retained separately.','','| Run | Wall seconds | User seconds | System seconds | Peak RSS MiB | Child exit |','| --- | ---: | ---: | ---: | ---: | ---: |']
for label in ['parent','head']:
 for kind in ['latent']:
  t=json.loads((out/f'{label}-{kind}.time.json').read_text())
  lines.append(f"| {label} tsc entry first-error | {t['wall_seconds']:.3f} | {t['user_seconds']:.3f} | {t['system_seconds']:.3f} | {t['peak_rss_kib']/1024:.2f} | {t['exit_code']} |")
lines+=['','Machine configuration is in [box.json](box.json). Setup, apply, compiler build, measurement and pairing logs are retained beside this report; streams over 1 MB are gzip compressed. [provenance.json](provenance.json) records SHAs and dependency pins; [adapted-source-hashes.json](adapted-source-hashes.json) records the shared tree bytes. Binary digests and all child timing records are retained. Final source-byte, completed-reach and archived-stream checks are in [validation.json](validation.json). Go evidence sources use `.go.txt` filenames.','', '## Reproduction','','```sh','source /workspace/adamic-tools/env.sh','bash cloud/setup.sh','npm ci --prefix /workspace/overload-parent/stage3/api','export ADAMIC_TYPESCRIPT_SOURCE=/workspace/overload-upstream','bash /workspace/overload-parent/stage3/apply.sh /workspace/overload-adapted','bash build.sh parent','bash build.sh head','bash measure.sh parent','bash measure.sh head','python3 /workspace/overload-parent/stage3/census/pair/pair.py parent-latent.jsonl.gz head-latent.jsonl.gz /workspace/overload-adapted --typescript /workspace/overload-parent/stage3/api/node_modules/typescript --json delta.json --report pair-report.md','```','','The helper scripts retain the exact absolute scratch paths used here. Recreate the two pinned worktrees and initialize their exact submodules first. `run.py` is the timing wrapper. This is observational lowering evidence with the latent census\'s existing eligibility and first-error limits, and does not produce native output.','']
lines += ['', '## Newly exposed findings', '', 'The two new findings are lowering first stops in already-blocked units. They are included in the 43 changed first stops, separately from regressions:', '', "- `src/compiler/visitorPublic.ts:526:9`: NotYet: a branded supertype inside a checked predicate's array target. First exposed in `visitFunctionBody` at `src/compiler/visitorPublic.ts:508:1`.", '- `src/compiler/factory/emitNode.ts:262:13`: NotYet: writing a possibly absent optional own field. First exposed in `transformES2018` at `src/compiler/transformers/es2018.ts:154:1`.', '', 'Panics: 0 parent, 0 head. No previously finding-free attempted unit gained a first stop, and no previously finding-free refusal-scan site gained a finding.', '']
